  if (p.t !== q.t) return p.t < q.t ? -1 : 1;
  if (p.c.uh !== q.c.uh) return p.c.uh < q.c.uh ? -1 : 1;
  if (p.c.ul !== q.c.ul) return p.c.ul < q.c.ul ? -1 : 1;
