    if (!(heap.length > 0 && heap[0].t < target)) {
      if (this.pending.length === 0) break;
      this.feed(); continue; // a flush can create events (RECEPTORs, 11.1)
    }
    const t = heap[0].t;
    if (this.pending.length > 0 && t > this.t_group) {
      this.feed();
      if (work >= cap) { this.t = this.t_group; this.lastWork = work; return this.t; }
      continue;
    }
    const trip = this.guardsUpto(t);
    if (trip) { this.close(trip[0], trip[1]); this.lastWork = work; return this.t; }
